.scratch-wrap {
  position: relative; width: 250px; height: 150px;
  border-radius: 15px; overflow: hidden;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  background: linear-gradient(135deg, #00ffcc, #00997a);
  display: flex; align-items: center; justify-content: center;
  color: #000; font-family: sans-serif; font-weight: 900; font-size: 24px;
}
.scratch-canvas {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 100%; z-index: 10;
  cursor: pointer; touch-action: none;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'scratch-wrap';
wrap.innerHTML = '<div>🎉 YOU WON $500!</div>';

const canvas = document.createElement('canvas');
canvas.className = 'scratch-canvas';
canvas.width = 250; canvas.height = 150;
wrap.appendChild(canvas);
c.appendChild(wrap);

const ctx = canvas.getContext('2d');
ctx.fillStyle = '#6c63ff';
ctx.fillRect(0, 0, 250, 150);
ctx.fillStyle = '#fff';
ctx.font = '20px sans-serif';
ctx.fillText('SCRATCH HERE', 45, 80);

let isScratching = false;

function scratch(e) {
  if (!isScratching) return;
  const rect = canvas.getBoundingClientRect();
  const x = (e.clientX || e.touches[0].clientX) - rect.left;
  const y = (e.clientY || e.touches[0].clientY) - rect.top;

  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.arc(x, y, 20, 0, Math.PI * 2);
  ctx.fill();
}

canvas.addEventListener('pointerdown', () => isScratching = true);
document.addEventListener('pointerup', () => isScratching = false);
canvas.addEventListener('pointermove', scratch);
